void Solver::rephase() {
    // Reset rephase counter
    rephases = 0;

    // Adjust threshold based on current performance
    if (conflicts > 0) {
        // Make threshold adaptive based on average trail length
        double avg_trail_length = (double)trail.size() / conflicts;
        threshold = std::max(100, (int)(avg_trail_length * 0.8));
    }

    // Increase rephase limit more aggressively for better exploration
    rephase_limit += 16384;

    // Update saved phases based on current assignment trends
    // This helps preserve good assignments while still allowing exploration
    for (int i = 1; i <= vars; i++) {
        if (value[i] != 0) {
            // Current assignment has been working (variable is assigned)
            saved[i] = value[i];
        } else if (local_best[i] != 0) {
            // Use local best if variable is unassigned
            saved[i] = local_best[i];
        }
        // Add some randomness (10%) to avoid getting stuck
        if (rand() % 10 == 0) {
            saved[i] = (rand() % 2 == 0) ? 1 : -1;
        }
    }
}
